Declare @var_subject varchar(200)
DECLARE @rec as varchar(100)
DECLARE @copy_rec varchar(255)
SET @var_subject =  'Duplicated Patient_Row_id in Patient Matching Service Input Files' 
SET @rec=@var_recipients
SET @copy_rec=@var_copy_recipients

EXEC msdb.dbo.sp_send_dbmail
	@recipients=@rec, 
	@copy_recipients=@copy_rec,
	@subject=@var_subject, 
	@body='There are duplicated patient_row_id in the patient matching service input files. Please check the file \\phsabc\root\BCCDC\Groups\Data_Surveillance\PHRDW\PMS\Duplicated_Patient.xlsx for the detail.',
	@importance ='HIGH'
